563	func SearchRepository(ctx context.Context, repo, providerVersion, query string, options SearchOptions) (SearchResponse, error) {
564		q := buildSearchQuery(query)
565		if len(q.terms) == 0 {
566			return SearchResponse{}, errors.New("search query has no meaningful terms")
567		}
568		if options.TopK <= 0 {
569			options.TopK = defaultSearchTopK
570		}
571		if options.ContextLines < 0 {
572			return SearchResponse{}, errors.New("search context lines cannot be negative")
573		}
574		if options.ContextLines == 0 {
575			options.ContextLines = defaultSearchContextLines
576		}
577		if options.MaxRegionLines <= 0 {
578			options.MaxRegionLines = defaultSearchMaxRegionLines
579		}
580		if options.MaxSnippetLines <= 0 {
581			options.MaxSnippetLines = defaultSearchMaxSnippetLines
582		}
583		if options.MaxRegionsPerFile <= 0 {
584			options.MaxRegionsPerFile = defaultSearchMaxRegionsPerFile
585		}
586		if options.MaxIndexedFiles <= 0 {
587			options.MaxIndexedFiles = defaultSearchIndexedFiles(options.TopK)
588		}
589		if options.Profile == "" {
590			// Fast, not syntax-only: graph-aware ranking (caller-degree boosts and
591			// relation expansion) needs call/construct edges over the indexed
592			// subset. Syntax-only emits none, which silently disables the graph
593			// half of hybrid search (graph_candidates is always 0).
594			options.Profile = ProfileFast
595		}
596		sparseQuery := buildSparseSearchQuery(query)
597		searchStarted := time.Now()
598		baseSnapshotOptions := ProviderSnapshotOptions{
599			NoNetwork:     true,
600			Worktree:      options.Worktree,
601			IgnoreFiles:   options.IgnoreFiles,
602			IncludeFiles:  options.IncludeFiles,
603			MaxParseBytes: options.MaxParseBytes,
604			Profile:       options.Profile,
605		}
606		var preindexedSnapshot ProviderSnapshot
607		preindexCacheHit := false
608		indexStarted := time.Now()
609		if !options.Worktree && !options.DisableCache {
610			var err error
611			preindexedSnapshot, preindexCacheHit, err = loadCachedCompleteSearchSnapshot(
612				ctx, repo, providerVersion, baseSnapshotOptions, options.CacheDir,
613			)
614			if err != nil {
615				return SearchResponse{}, err
616			}
617		}
618		preindexLoadLatency := time.Since(indexStarted)
619		preselectStarted := time.Now()
620		selection, err := preselectSearchFiles(
621			ctx, repo, q, sparseQuery, options, preindexedSnapshot, preindexCacheHit,
622		)
623		if err != nil {
624			return SearchResponse{}, err
625		}
626		preselectLatency := time.Since(preselectStarted)
627		selectedFiles := selection.files
628		if len(selectedFiles) == 0 {
629			// A no-hit query still reports the health of an already-preindexed HEAD
630			// graph. Do not build a cold graph merely to return no results, but do
631			// preserve cached partial failures/completeness and cache-hit provenance.
632			cachedSnapshot, cacheHit := preindexedSnapshot, preindexCacheHit
633			// Tree, not commit, is what determines whether the graph is still valid:
634			// two different commits sharing a tree parse identically, so only a tree
635			// change mid-search is a real race worth rejecting.
636			if cacheHit && selection.commit != "" && cachedSnapshot.Header.Tree != selection.tree {
637				return SearchResponse{}, errors.New("repository HEAD changed during search; retry against a stable commit")
638			}
639			totalLatency := time.Since(searchStarted).Milliseconds()
640			repoRoot, commit, tree := selection.repoRoot, selection.commit, selection.tree
641			warnings := selection.warnings
642			partialFailures := []PartialFailure{}
643			completeness := CompletenessReport{Languages: map[string]LanguageCompleteness{}, Relations: map[string]int{}}
644			symbolsConsidered := 0
645			if cacheHit {
646				repoRoot = cachedSnapshot.Header.RepoRoot
647				commit = cachedSnapshot.Header.Commit
648				tree = cachedSnapshot.Header.Tree
649				warnings = cachedSnapshot.Header.Warnings
650				partialFailures = cachedSnapshot.Header.PartialFailures
651				if partialFailures == nil {
652					partialFailures = []PartialFailure{}
653				}
654				completeness = cachedSnapshot.Header.Completeness
655				symbolsConsidered = len(cachedSnapshot.Symbols)
656			}
657			return SearchResponse{
658				Query:    query,
659				RepoRoot: repoRoot,
660				Commit:   commit,
661				Tree:     tree,
662				Profile:  string(options.Profile),
663				Results:  []SearchResult{},
664				Stats: SearchStats{
665					FilesScanned:              selection.filesScanned,
666					PreselectionBackend:       selection.preselectionBackend,
667					PreselectionPasses:        selection.preselectionPasses,
668					PreselectionFilesExamined: selection.preselectionFilesExamined,
669					FilesContentRead:          selection.filesContentRead,
670					FilesIndexed:              0,
671					SymbolsConsidered:         symbolsConsidered,
672					ResultBytes:               serializedSearchResultBytes([]SearchResult{}),
673					ContextBudgetBytes:        options.MaxContextBytes,
674					IndexCacheHit:             cacheHit,
675					IndexLatencyMS:            preindexLoadLatency.Milliseconds(),
676					PreselectLatencyMS:        preselectLatency.Milliseconds(),
677					TotalLatencyMS:            totalLatency,
678					SearchLatencyMS:           totalLatency,
679				},
680				Warnings:        warnings,
681				PartialFailures: partialFailures,
682				Completeness:    completeness,
683			}, nil
684		}
685	
686		// The provider graph and lexical query scope must describe the same files.
687		// A complete preindex can supply cached parse output, but search derives the
688		// exact selective graph so cache presence cannot change relation expansion.
689		onlyFiles := selectedFiles
690		if options.IndexAllFiles || len(selectedFiles) == selection.filesScanned {
691			// Canonicalize complete snapshots to the query-independent cache key so
692			// `graph index` and all-files search share one durable artifact.
693			onlyFiles = nil
694		}
695		snapshotOptions := baseSnapshotOptions
696		snapshotOptions.OnlyFiles = onlyFiles
697		snapshot, cacheHit := preindexedSnapshot, preindexCacheHit
698		indexLatency := preindexLoadLatency
699		if cacheHit && len(snapshotOptions.OnlyFiles) > 0 {
700			// The preindexed complete snapshot never serves a selective query
701			// directly: the loader reuses the per-query selective cache entry, only
702			// derives from the complete snapshot on a miss, and falls back to an
703			// ordinary build when derivation fails (for example after a HEAD move).
704			indexStarted = time.Now()
705			snapshot, cacheHit, err = loadOrDeriveSelectiveSearchSnapshot(
706				ctx, repo, providerVersion, snapshotOptions, options.CacheDir, options.DisableCache, preindexedSnapshot,
707			)
708			if err != nil {
709				return SearchResponse{}, err
710			}
711			indexLatency += time.Since(indexStarted)
712		} else if !cacheHit {
713			indexStarted = time.Now()
714			snapshot, cacheHit, err = loadOrBuildSearchGraphSnapshot(ctx, repo, providerVersion, snapshotOptions, options.CacheDir, options.DisableCache)
715			if err != nil {
716				return SearchResponse{}, err
717			}
718			indexLatency += time.Since(indexStarted)
719		}
720		// See the analogous no-hit guard above: tree identity is what matters here.
721		if selection.commit != "" && snapshot.Header.Tree != selection.tree {
722			return SearchResponse{}, errors.New("repository HEAD changed during search; retry against a stable commit")
723		}
724		queryStarted := time.Now()
725		useHead := !options.Worktree && snapshot.Header.Commit != ""
726		read, closeSource, err := openSearchContentReader(
727			ctx, repo, snapshot.Header.Commit, useHead, options.IgnoreFiles, options.IncludeFiles,
728		)
729		if err != nil {
730			return SearchResponse{}, err
731		}
732		if closeSource != nil {
