734		}
735		queryReads := &searchContentReadTracker{read: read}
736		read = cachedContentReader(queryReads.Read)
737		// The repository-wide literal lookup two blocks share. It reuses the per-term posting lists
738		// preselection already built, so it adds no corpus pass; see search_needle.go for the three
739		// sources and why it answers nothing when none of them is exact.
740		needleIndex := &searchNeedleIndex{read: read, corpus: selection.allFiles}
741		needleIndex.termFiles, needleIndex.termFileTotals = selection.termPostings.snapshot()
742		if selection.gitGrepUsable {
743			treeish := selection.gitGrepTreeish
744			needleIndex.grep = func(pattern string) ([]string, bool) {
745				paths, grepErr := gitutil.GrepFixedStringPaths(ctx, selection.repoRoot, treeish, pattern)
746				return paths, grepErr == nil
747			}
748		}
749	
750		symbolsByFile := make(map[string][]SymbolRecord)
751		symbolsByID := make(map[string]SymbolRecord, len(snapshot.Symbols))
752		for _, symbol := range snapshot.Symbols {
753			symbolsByFile[symbol.FilePath] = append(symbolsByFile[symbol.FilePath], symbol)
754			symbolsByID[symbol.ID] = symbol
755		}
756		for filePath := range symbolsByFile {
757			sort.Slice(symbolsByFile[filePath], func(i, j int) bool {
758				left, right := symbolsByFile[filePath][i], symbolsByFile[filePath][j]
759				if left.StartLine != right.StartLine {
760					return left.StartLine < right.StartLine
761				}
762				return left.EndLine < right.EndLine
763			})
764		}
765	
766		fileLanguages := make(map[string]string, len(snapshot.Files))
767		for _, file := range snapshot.Files {
768			fileLanguages[file.Path] = file.Language
769		}
770	
771		fileDF := make(map[string]int, len(q.terms))
772		sparseDF := selection.sparseDF
773		if sparseDF == nil {
774			sparseDF = make(map[string]int, len(sparseQuery.terms))
775		}
776		sparseDocumentCount := selection.sparseDocumentCount
777		sparseDocumentLength := selection.sparseDocumentLength
778		var candidates []searchCandidate
779		sparseCandidates := append([]searchCandidate(nil), selection.sparseCandidates...)
780		// Corpus statistics come first, in their own pass. Scoring has to know which query
781		// words this repository can match at all before a single candidate is built: the
782		// all-or-nothing bonuses (exact-symbol, all-query-terms) are otherwise judged against
783		// words nothing contains, which silently penalizes the documents that matched the rest
784		// of the query. The content reader is memoized, so the second pass normally re-reads
785		// nothing; a selection larger than the content cache can fall back to disk for the
786		// overflow, which rereadFiles/rereadBytes below keep out of the read telemetry.
787		indexableFiles := make([]string, 0, len(selectedFiles))
788		for _, filePath := range selectedFiles {
789			if err := ctx.Err(); err != nil {
790				return SearchResponse{}, err
791			}
792			content, ok := read(filePath)
793			if !ok || strings.IndexByte(content, 0) >= 0 {
794				continue
795			}
796			indexableFiles = append(indexableFiles, filePath)
797			lowerContent := strings.ToLower(content)
798			lowerPath := strings.ToLower(filepath.ToSlash(filePath))
799			for _, term := range q.terms {
800				if strings.Contains(lowerContent, term) || strings.Contains(lowerPath, term) {
801					fileDF[term]++
802				}
803			}
804		}
805		q = q.withCorpusPresence(fileDF)
806		statisticsPassFiles, statisticsPassBytes := queryReads.files, queryReads.bytes
807		for _, filePath := range indexableFiles {
808			if err := ctx.Err(); err != nil {
809				return SearchResponse{}, err
810			}
811			content, ok := read(filePath)
812			if !ok {
813				continue
814			}
815			lines := strings.Split(content, "\n")
816			candidates = append(candidates, candidatesForFile(
817				q, filePath, fileLanguages[filePath], lines, symbolsByFile[filePath], options,
818			)...)
819		}
820		// Re-reading a file the content cache had to drop pulls in the same file, not another
821		// one, so it must not inflate what the query is reported to have read.
822		rereadFiles := queryReads.files - statisticsPassFiles
823		rereadBytes := queryReads.bytes - statisticsPassBytes
824		sparseFilesRead := selection.sparseFilesContentRead
825		if options.Deep && len(sparseQuery.terms) > 0 {
826			for _, filePath := range selection.sparseFiles {
827				if selection.sparsePrecomputedFiles[filePath] {
828					continue
829				}
830				if err := ctx.Err(); err != nil {
831					return SearchResponse{}, err
832				}
833				content, ok := read(filePath)
834				sparseFilesRead++
835				if !ok || len(content) > maxSparseSearchFileBytes || strings.IndexByte(content, 0) >= 0 {
