844					language = spec.language
845				}
846				fileSparse, documentCount, documentLength := sparseCandidatesForFile(
847					sparseQuery, filePath, language, lines, options,
848				)
849				sparseCandidates = append(sparseCandidates, fileSparse...)
850				sparseDocumentCount += documentCount
851				sparseDocumentLength += documentLength
852				for _, candidate := range fileSparse {
853					for term := range candidate.termCounts {
854						sparseDF[term]++
855					}
856				}
857			}
858			if len(selection.sparseFiles) > 0 && len(selection.sparseFiles) < selection.filesScanned {
859				sparseDocumentCount = scaleSearchCorpusValue(
860					sparseDocumentCount, selection.filesScanned, len(selection.sparseFiles),
861				)
862				sparseDocumentLength = scaleSearchCorpusValue(
863					sparseDocumentLength, selection.filesScanned, len(selection.sparseFiles),
864				)
865			}
866		}
867	
868		stats := SearchStats{
869			FilesScanned:              selection.filesScanned,
870			PreselectionBackend:       selection.preselectionBackend,
871			PreselectionPasses:        selection.preselectionPasses,
872			PreselectionFilesExamined: selection.preselectionFilesExamined,
873			FilesContentRead:          selection.filesContentRead,
874			FilesIndexed:              len(selectedFiles),
875			SymbolsConsidered:         len(snapshot.Symbols),
876			LexicalCandidates:         len(candidates),
877			SparseCandidates:          len(sparseCandidates),
878			SparseFilesRead:           sparseFilesRead,
879			IndexCacheHit:             cacheHit,
880			IndexLatencyMS:            indexLatency.Milliseconds(),
