888		graphCandidates := expandGraphCandidates(candidates, q, snapshot.Relations, symbolsByID, callerBoosts, read, fileLanguages, options)
889		stats.GraphCandidates = len(graphCandidates)
890		stats.CallerBoostedCandidates += countSearchCandidatesWithSignal(graphCandidates, "graph:callers")
891		candidates = append(candidates, graphCandidates...)
892		sortSearchCandidates(candidates)
893		expansionSeeds := append([]searchCandidate(nil), candidates...)
894		usageFilesBefore := queryReads.files
895		usageBytesBefore := queryReads.bytes
896		usagePreselection := searchScanTelemetry{}
897		identifierUsages := expandIdentifierUsageCandidates(
898			ctx, expansionSeeds, q, symbolsByID, symbolsByFile, read, fileLanguages, options,
899			committedUsageFileSelector(
900				repo, selection.commit, useHead, fileLanguages, options.Deep, selection.filesScanned, &usagePreselection,
901			),
902		)

