#!/usr/bin/env python3
"""CORRECTED: separate `entire graph <verb>` tool calls from genuine shell exploration,
and split both by phase (before/after first Edit|Write). Read-only."""
import json, os, re, glob, collections, statistics

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)

# a graph invocation, in any of its spellings
GRAPH = re.compile(r'(?:^|[;&|]\s*|\s)(?:entire\s+graph|eg-q(?:\.run)?|\./eg-q|entire-graph)\s+(\w+)')
SHELL_EXPLORE = re.compile(r'(?:^|[;&|]\s*)\s*(?:sudo\s+|time\s+|env\s+\S+=\S+\s+)*(grep|egrep|fgrep|rg|ag|ack|find|locate|cat|head|tail|sed|awk|ls)\b')
BUILDLIKE = re.compile(r'\b(make|cmake|go\s+(build|test|vet)|cargo|mvn|gradle|npm|npx|pnpm|yarn|pytest|phpunit|composer|bundle|rake|rspec|ctest|javac|tsc|jest|vitest|runtest|\./configure)\b')

def strip_graph(cmd):
    """remove every `entire graph ...` segment so its args don't look like shell exploration"""
    return GRAPH.sub(' __GRAPHCALL__ ', cmd)

def scan(arm):
    base = f"{S}/results/REP50_r1_{arm}/{arm}"
    per = []
    for iid in sorted(os.listdir(base)):
        d = f"{base}/{iid}"; cc = f"{d}/cc_out.json"
        if not os.path.exists(cc) or os.path.getsize(cc) == 0: continue
        sid = (json.load(open(cc)) or {}).get("session_id")
        r = collections.Counter(); phase = 0
        for f in tx.get(sid or "", []):
            for line in open(f, errors="replace"):
                try: o = json.loads(line)
                except Exception: continue
                m = o.get("message") or {}
                for b in (m.get("content") or []) if isinstance(m.get("content"), list) else []:
                    if not isinstance(b, dict) or b.get("type") != "tool_use": continue
                    nm = b.get("name"); inp = b.get("input") or {}
                    if nm in ("Edit","MultiEdit","Write","NotebookEdit"):
                        r["edit"] += 1; phase = 1; continue
                    if nm == "Read":
                        r["read"] += 1; r["read_post" if phase else "read_pre"] += 1; continue
                    if nm != "Bash": continue
                    cmd = inp.get("command") or ""
                    gcalls = GRAPH.findall(cmd)
                    if gcalls:
                        for v in gcalls:
                            r["graph"] += 1; r[f"graph_{v}"] += 1
                            r["graph_post" if phase else "graph_pre"] += 1
                    rest = strip_graph(cmd)
                    if BUILDLIKE.search(rest):
                        r["build"] += 1; r["build_post" if phase else "build_pre"] += 1
                    elif SHELL_EXPLORE.search(rest):
                        r["shell"] += 1; r["shell_post" if phase else "shell_pre"] += 1
                    elif not gcalls:
                        r["other"] += 1
        per.append(r)
    return per

out = {}
for arm in ("baseline","eg"):
    per = scan(arm); out[arm] = per
    T = collections.Counter()
    for p in per: T.update(p)
    n = len(per)
    print(f"\n===== {arm.upper()}  (n={n} sessions) =====")
    print(f"  SHELL EXPLORATION  total {T['shell']:>4}   pre-edit {T['shell_pre']:>4}   post-edit {T['shell_post']:>4}   "
          f"({100*T['shell_post']/max(1,T['shell']):.0f}% post)")
