#!/usr/bin/env python3
"""Does an OAuth/subscription-authenticated Claude Code session populate cost + usage?
Read-only. Never prints any credential value."""
import json, os, glob

home = os.path.expanduser("~")
# 1. auth mode (keys only, no values)
try:
    d = json.load(open(os.path.join(home, ".claude.json")))
    keys = [k for k in d if any(s in k.lower() for s in ("auth", "oauth", "subscription", "api"))]
    print("auth-related keys in .claude.json:", keys)
    oa = d.get("oauthAccount")
    if isinstance(oa, dict):
        print("oauthAccount subkeys:", sorted(oa.keys()))
except Exception as e:
    print("could not read .claude.json:", type(e).__name__)

# 2. newest transcripts -> is costUSD / usage present?
fs = sorted(glob.glob(os.path.join(home, ".claude/projects/**/*.jsonl"), recursive=True),
            key=lambda p: os.path.getmtime(p), reverse=True)[:3]
print(f"\nchecked {len(fs)} newest transcripts")
for f in fs:
    ncost = 0; sumcost = 0.0; nusage = 0; outtok = 0; seen = set()
    for line in open(f, errors="replace"):
        try: o = json.loads(line)
        except Exception: continue
        for holder in (o, o.get("message") or {}):
            if isinstance(holder, dict) and holder.get("costUSD") is not None:
                ncost += 1; sumcost += holder["costUSD"] or 0
        m = o.get("message") or {}
        u = m.get("usage")
        if u and m.get("id") not in seen:
            seen.add(m.get("id")); nusage += 1
            outtok += u.get("output_tokens", 0) or 0
    print(f"  {os.path.basename(f)[:16]}… size={os.path.getsize(f):>9,}  "
          f"costUSD_records={ncost} sum=${sumcost:.4f}  usage_msgs={nusage} out_tok={outtok:,}")

# 3. the field the GATE reads is total_cost_usd in the FINAL result object
print("\nlooking for a final-result object carrying total_cost_usd ...")
found = 0
for f in fs:
    for line in open(f, errors="replace"):
        if '"total_cost_usd"' in line:
            try: o = json.loads(line)
            except Exception: continue
            print(f"  {os.path.basename(f)[:16]}… total_cost_usd={o.get('total_cost_usd')} "
                  f"subtype={o.get('subtype')} turns={o.get('num_turns')}")
            found += 1
            break
if not found:
    print("  none in these transcripts (interactive sessions do not emit the -p result object)")

