func openSearchContentReader(
	ctx context.Context,
	repo, commit string,
	useHead bool,
	ignoreFiles, includeFiles []string,
) (contentReader, func() error, error) {
	if useHead {
		batch, err := gitutil.NewBatchFileReader(ctx, repo, commit)
		if err != nil {
			return nil, nil, err
		}
		// Snippet and body reads never need a file the indexer refuses to parse,
		// so the reader declines it rather than materializing it twice over.
		batch.SetMaxBytes(defaultMaxParseBytes)
		read := func(path string) (string, bool) {
			if strings.Contains(path, "\n") {
				content, ok, err := gitutil.ShowFile(ctx, repo, commit, path)
				return content, ok && err == nil
			}
			content, ok, err := batch.ReadFile(path)
			return content, ok && err == nil
		}
		return read, batch.Close, nil
	}
	opened, err := openSource(ctx, repo, "", sourceOptions{
		ignoreFiles:  ignoreFiles,
		includeFiles: includeFiles,
		maxReadBytes: defaultMaxParseBytes,
	})
	if err != nil {
		return nil, nil, err
	}
	return opened.read, opened.close, nil
}

func defaultSearchIndexedFiles(topK int) int {
	// Shallow interactive searches keep the original cold-start bound. Deeper
	// rankings need a wider file pool or preselection becomes the recall limit
	// before TopK and per-file diversity can take effect.
	//

=== how changed.go gets its snapshot + any reader ===
	cacheDir := resolveCacheDir(flags.CacheDir, opts.Env.PluginDataDir)

	totalStarted := time.Now()
	files, err := gitutil.WorktreeChangedFiles(ctx, repo)
	if err != nil {
		return err
	}

	indexStarted := time.Now()
	// The working tree is the whole point of this verb, so Worktree is forced on
	// rather than taken from the flag: a committed-tree snapshot cannot contain
	// the edit being asked about.
	snapshot, cacheHit, err := sem.LoadOrBuildProviderSnapshot(ctx, repo, opts.Version, sem.ProviderSnapshotOptions{
		NoNetwork:    true,
		Worktree:     true,
		IgnoreFiles:  flags.IgnoreFile,
		IncludeFiles: flags.IncludeFile,
		Profile:      profile,
	}, cacheDir, flags.DisableCache)
	if err != nil {
		return err
	}
	indexLatency := time.Since(indexStarted)

	queryStarted := time.Now()
	response := buildChangedResponse(snapshot, files, flags.Limit)
	response.RepoRoot = snapshot.Header.RepoRoot
	response.Head = snapshot.Header.Commit
	response.Warnings = snapshot.Header.Warnings
	response.PartialFailures = snapshot.Header.PartialFailures
	response.IndexCacheHit = cacheHit
	response.IndexCacheDisabled = cacheDir == "" || flags.DisableCache
	response.IndexLatencyMS = indexLatency.Milliseconds()
	response.QueryLatencyMS = time.Since(queryStarted).Milliseconds()
	response.TotalLatencyMS = time.Since(totalStarted).Milliseconds()

	if flags.Format == "json" {
		encoder := json.NewEncoder(opts.Stdout)
		encoder.SetIndent("", "  ")
		return encoder.Encode(response)
	}
	writeChangedText(opts, response)
	return nil
