package sem

import (
	"testing"
)

// VerifyCommandForFile is the post-edit entry point: it answers "how do I verify THIS file"
// without a ranking in hand. These tests pin the two properties that make it usable there —
// it derives for the file it was asked about, and it is the same ladder search runs.

func TestVerifyCommandForFileDerivesForTheFileAsked(t *testing.T) {
	t.Parallel()
	files := map[string]string{
		"go.mod":                      "module github.com/example/proj\n",
		"internal/cli/changed.go":     "package cli\n",
		"internal/cli/doctor.go":      "package cli\n",
		"internal/cli/doctor_test.go": "package cli\n\nfunc TestDoctorPrintsEnv(t *testing.T) {}\n",
	}
	read := func(path string) (string, bool) { content, ok := files[path]; return content, ok }

	// changed.go has NO test of its own. The ladder must fall back to changed.go's own package or
	// the suite -- it must NOT borrow doctor_test.go, which is the failure the --path hack produced.
	got := VerifyCommandForFile(read, "internal/cli/changed.go", "", "")
	if got == nil {
		t.Fatal("VerifyCommandForFile returned nil; the residual floor must always fire")
	}
	if got.Targets == "internal/cli/doctor_test.go" {
		t.Fatalf("derived a verify for an unrelated file's test: %+v", got)
	}
	// A Go module is present, so it must reach a real command rather than the residual floor.
	if got.Tier == searchVerifyTierNone {
		t.Fatalf("go.mod present but ladder fell to the residual floor: %+v", got)
	}
	if got.Command == "" {
		t.Fatalf("empty command: %+v", got)
	}
}

func TestVerifyCommandForFileUsesACallerSuppliedTest(t *testing.T) {
	t.Parallel()
	files := map[string]string{
		"go.mod":                       "module github.com/example/proj\n",
		"internal/cli/changed.go":      "package cli\n",
		"internal/cli/changed_test.go": "package cli\n\nfunc TestChangedReportsHunks(t *testing.T) {}\n",
	}
	read := func(path string) (string, bool) { content, ok := files[path]; return content, ok }

	got := VerifyCommandForFile(read,
		"internal/cli/changed.go", "internal/cli/changed_test.go", "TestChangedReportsHunks")
	if got == nil {
		t.Fatal("nil command")
	}
	if got.Tier != searchVerifyTierNarrow {
		t.Fatalf("a named covering test must reach the narrow rung, got tier=%q cmd=%q",
			got.Tier, got.Command)
	}
	if got.Command == "" || got.Targets != "internal/cli/changed_test.go" {
		t.Fatalf("wrong subject: %+v", got)
	}
}

// The extraction must not have changed the ladder: the exported wrapper and the internal
// entry point must agree for the same subject.
func TestVerifyCommandForFileMatchesTheInternalLadder(t *testing.T) {
	t.Parallel()
	files := map[string]string{
		"go.mod":                       "module github.com/example/proj\n",
		"internal/cli/changed.go":      "package cli\n",
		"internal/cli/changed_test.go": "package cli\n\nfunc TestChangedReportsHunks(t *testing.T) {}\n",
	}
	read := func(path string) (string, bool) { content, ok := files[path]; return content, ok }

	subject := searchVerifySubject{
		sourcePath:   "internal/cli/changed.go",
		testPath:     "internal/cli/changed_test.go",
		testName:     "TestChangedReportsHunks",
		testEvidence: "caller-supplied test path",
	}
	want := buildSearchVerifyForSubject(subject, searchVerifyTestEvidence(files))
	got := VerifyCommandForFile(read,
		"internal/cli/changed.go", "internal/cli/changed_test.go", "TestChangedReportsHunks")

	if want == nil || got == nil {
		t.Fatalf("nil: want=%v got=%v", want, got)
	}
	if got.Command != want.Command || got.Targets != want.Targets ||
		got.DerivedFrom != want.DerivedFrom || got.Tier != want.Tier {
		t.Fatalf("wrapper diverged from the ladder:\n got=%+v\nwant=%+v", got, want)
	}
}

func TestVerifyCommandForFileNeverReturnsNil(t *testing.T) {
	t.Parallel()
	empty := func(string) (string, bool) { return "", false }
	for _, path := range []string{"", "src/nothing.xyz"} {
		got := VerifyCommandForFile(empty, path, "", "")
		if got == nil {
			t.Fatalf("nil for path %q; silent absence is the failure the residual floor exists to prevent", path)
		}
		if got.Tier != searchVerifyTierNone {
			t.Fatalf("path %q: expected the residual floor, got tier=%q", path, got.Tier)
		}
	}
}

