#!/usr/bin/env python3
"""GATE 2 v2: burn = OBSERVED (has results) or TUNED-ON (member of a config-selecting selector).
Merely appearing in a superset task listing is NOT a burn. Read-only."""
import json, os, glob, collections

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
def tids(p):
    if not os.path.exists(p): return set()
    d = json.load(open(p))
    if isinstance(d, dict) and "instances" in d: return {x["instance_id"] for x in d["instances"]}
    if isinstance(d, list): return {x if isinstance(x,str) else x.get("instance_id") for x in d}
    return set()
def xids(p): return {l.strip() for l in open(p) if l.strip()} if os.path.exists(p) else set()

pool = tids(f"{S}/tasks/multilingual_300.json")

# HARD BURN 1 — actually executed (a results dir exists anywhere)
ran = {os.path.basename(d) for d in glob.glob(f"{S}/results/*/*/*") if os.path.isdir(d)}

# HARD BURN 2 — selectors that were used to CHOOSE a config or were declared holdouts
TUNED = ["val30","h30","hk30","ho5","ho10","ho20","screen6",
         "gate_5","gate_10","gate_20","gate_30","gate_60","gate_300",
         "prereg30","prereg100","strat60","f5","o10","s20","fb5","op10","sn20"]
tuned = set()
for n in TUNED: tuned |= xids(f"{S}/.elig_{n}.txt")

# HARD BURN 3 — cells whose identities were read per-instance
for t in ["rep50","rep50_run","g1","g2","g3","fab82","rep30_tasks"]:
    tuned |= tids(f"{S}/tasks/{t}.json")

burned = (ran | tuned) & pool
clean = pool - burned
print(f"pool                     : {len(pool)}")
print(f"  executed (results dir) : {len(ran & pool)}")
print(f"  tuned-on / declared    : {len(tuned & pool)}")
print(f"  union burned           : {len(burned)}")
print(f"  CLEAN                  : {len(clean)}")

have = set()
gd = f"{S}/graphs"
if os.path.isdir(gd):
    have = {i for i in os.listdir(gd)
            if os.path.exists(f"{gd}/{i}/graph.edges.ndjson") or os.path.exists(f"{gd}/{i}/graph.symbols.ndjson")}
ready = clean & have
print(f"  CLEAN and graph-ready  : {len(ready)}")

