#!/usr/bin/env python3
"""Why did losers lose? Test competing mechanisms on rep50's 49 gated pairs.
H1 band effect: loss predicted by SHORT baseline (regression to mean / tool overhead on easy tasks)
H2 scope creep: eg edits MORE files (related sites) -> each extra edit costs a verify cycle
H3 retrieval miss: payload did not name the file eg eventually edited
H4 tool churn: eg made more graph calls chasing a bad first answer
H5 pre-treatment difficulty: loss predicted by language / patch fan-out (deployable if true)"""
import json, os, re, glob, statistics, math, collections

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)
GRAPH = re.compile(r'(?:^|[;&|]\s*|\s)(?:entire\s+graph|eg-q(?:\.run)?|entire-graph)\s+(\w+)')
SHELL = re.compile(r'(?:^|[;&|]\s*)\s*(?:sudo\s+|time\s+)*(grep|egrep|fgrep|rg|ag|ack|find|locate|cat|head|tail|sed|awk|ls)\b')
BUILD = re.compile(r'\b(make|cmake|go\s+(build|test|vet)|cargo|mvn|gradle|npm|npx|pnpm|yarn|pytest|phpunit|composer|bundle|rake|rspec|ctest|javac|tsc|jest|vitest|runtest)\b')
EXT = r'(?:go|py|js|ts|tsx|jsx|rs|java|rb|php|c|h|cc|cpp|hpp|kt|swift|scala|cs|m)'
PATHANY = re.compile(r'([\w./-]+\.' + EXT + r')')

def patch_files(p):
    s = set()
    if os.path.exists(p):
        for L in open(p, errors="replace"):
            if L.startswith('+++ b/'): s.add(L[6:].strip())
    return {x for x in s if x and x != '/dev/null'}

def arm(a):
    base = f"{S}/results/REP50_r1_{a}/{a}"; out = {}
    for iid in sorted(os.listdir(base)):
        d = f"{base}/{iid}"; cc = f"{d}/cc_out.json"
        if not os.path.exists(cc) or os.path.getsize(cc) == 0: continue
        j = json.load(open(cc)); u = j.get("usage") or {}
        r = dict(d=d, turns=j.get("num_turns") or 0, sid=j.get("session_id"),
                 tot=sum(u.get(k,0) for k in ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens")),
                 files=len(patch_files(f"{d}/patch.diff")),
                 psize=os.path.getsize(f"{d}/patch.diff") if os.path.exists(f"{d}/patch.diff") else 0,
                 edits=0, shell_post=0, gq=0)
        gq = f"{d}/gq_calls.log"
        if os.path.exists(gq) and os.path.getsize(gq): r["gq"] = sum(1 for _ in open(gq))
        phase = 0
        for f in tx.get(r["sid"] or "", []):
            for line in open(f, errors="replace"):
                try: o = json.loads(line)
                except Exception: continue
                m = o.get("message") or {}
                for b in (m.get("content") or []) if isinstance(m.get("content"), list) else []:
                    if not isinstance(b, dict) or b.get("type") != "tool_use": continue
                    nm = b.get("name")
                    if nm in ("Edit","MultiEdit","Write","NotebookEdit"): r["edits"] += 1; phase = 1; continue
                    if nm != "Bash" or not phase: continue
                    cmd = (b.get("input") or {}).get("command") or ""
                    rest = GRAPH.sub(' ', cmd)
                    if GRAPH.search(cmd) and not SHELL.search(rest): continue
                    if SHELL.search(rest) and not BUILD.search(rest): r["shell_post"] += 1
        # did the payload name the file eg edited?
        pp = f"{d}/gq_calls.log.payload"
        r["hit"] = None
        if a == "eg" and os.path.exists(pp) and os.path.getsize(pp):
            names = {os.path.basename(x) for x in PATHANY.findall(open(pp, errors="replace").read())}
            ed = patch_files(f"{d}/patch.diff")
            r["hit"] = bool(ed) and any(os.path.basename(x) in names for x in ed)
        out[iid] = r
    return out

B, E = arm("baseline"), arm("eg")
meta = {}
d = json.load(open(f"{S}/tasks/multilingual_300.json"))
for r in (d["instances"] if isinstance(d, dict) else d):
    if isinstance(r, dict): meta[r["instance_id"]] = r.get("language") or r.get("lang") or "?"

rows = []
for i in sorted(set(B) & set(E)):
    b, e = B[i], E[i]
    if not (b["tot"] and e["tot"]): continue
    rows.append(dict(iid=i, lang=meta.get(i, "?"), dtok=1 - e["tot"]/b["tot"],
                     bt=b["turns"], et=e["turns"], dturn=e["turns"]-b["turns"],
                     dedit=e["edits"]-b["edits"], befiles=b["files"], egfiles=e["files"],
                     dfiles=e["files"]-b["files"], dshell=e["shell_post"]-b["shell_post"],
                     gq=e["gq"], hit=e["hit"]))
W = [r for r in rows if r["dtok"] > 0]; L = [r for r in rows if r["dtok"] <= 0]
def med(g, k): return statistics.median([x[k] for x in g]) if g else float('nan')
def corr(xs, ys):
    mx, my = statistics.mean(xs), statistics.mean(ys)
    n = sum((a-mx)*(b-my) for a, b in zip(xs, ys))
    d_ = math.sqrt(sum((a-mx)**2 for a in xs) * sum((b-my)**2 for b in ys))
    return n/d_ if d_ else float('nan')

print(f"n={len(rows)}  winners={len(W)}  losers={len(L)}\n")
print(f"{'metric':<28}{'WINNERS':>10}{'LOSERS':>10}")
for k, lab in [("bt","baseline turns"),("et","eg turns"),("dturn","delta turns"),
               ("dedit","delta EDITS (eg-base)"),("befiles","baseline files patched"),
               ("egfiles","eg files patched"),("dfiles","delta files patched"),
               ("dshell","delta post-edit shell"),("gq","eg graph calls")]:
    print(f"  {lab:<26}{med(W,k):>10.1f}{med(L,k):>10.1f}")

print("\nH-tests (corr with token saving, n=49):")
for k, lab in [("bt","H1 baseline turns (band)"),("dedit","H2 extra edits"),
               ("dfiles","H2b extra files patched"),("dshell","H_post extra post-edit shell"),
               ("gq","H4 graph call count"),("dturn","delta turns")]:
    print(f"  {lab:<32} r = {corr([x[k] for x in rows],[x['dtok'] for x in rows]):+.3f}")

hits = [r for r in rows if r["hit"] is True]; miss = [r for r in rows if r["hit"] is False]
print(f"\nH3 retrieval: payload named the edited file")
print(f"  hit  n={len(hits):<3} median token delta {100*med(hits,'dtok'):+6.1f}%")
print(f"  miss n={len(miss):<3} median token delta {100*med(miss,'dtok'):+6.1f}%")

print("\nH5 pre-treatment: by language (n>=4 only)")
byl = collections.defaultdict(list)
for r in rows: byl[r["lang"]].append(r)
for lang, g in sorted(byl.items(), key=lambda kv: -len(kv[1])):
    if len(g) >= 4:
        print(f"  {lang:<12} n={len(g):<3} median {100*med(g,'dtok'):+6.1f}%  win-rate {sum(1 for x in g if x['dtok']>0)}/{len(g)}")
print("\nH5b pre-treatment: by BASELINE patch fan-out (files the no-tool arm touched)")
for lo, hi, lab in [(0,1,"1 file"),(2,3,"2-3 files"),(4,999,"4+ files")]:
    g = [r for r in rows if lo <= r["befiles"] <= hi]
    if g: print(f"  {lab:<10} n={len(g):<3} median {100*med(g,'dtok'):+6.1f}%  win-rate {sum(1 for x in g if x['dtok']>0)}/{len(g)}")

