=== the response struct fields ===
type posteditResponse struct {
	RepoRoot string `json:"repo_root"`
	Head     string `json:"head"`
	// Files is every path that differs from HEAD, whether or not the graph
	// resolved a definition inside it, so a caller sees coverage rather than
	// guessing at it.
	Files []changedFile `json:"files"`
	// Symbols are the definitions whose current bodies overlap a changed hunk,
	// most-depended-on first, bounded by --limit.
	Symbols []changedSymbol `json:"symbols"`
	// TotalSymbols is the count before that bound.
	TotalSymbols int `json:"total_symbols"`
	// SuppressedInventoryRecords counts definitions dropped from the ranking
	// because their language is parsed for inventory only. Reported rather than
	// discarded silently: a caller editing Markdown deserves to know its records
	// exist and were not ranked.
	SuppressedInventoryRecords int `json:"suppressed_inventory_records"`
	// Risks are the call sites this edit may have broken. See posteditRisks.
	Risks []posteditRisk `json:"risks"`
	// RiskTotal is the count before posteditRiskLimit.
	RiskTotal int `json:"risk_total"`
	// UnreadableFiles are edited paths whose current parse produced no
	// definitions where the committed tree had some. That is the signature of a
	// file mid-edit that no longer parses, and it suppresses the
	// no-longer-resolves check for that path — see posteditRisks.
	UnreadableFiles []string `json:"unreadable_files,omitempty"`
	// Verify is the narrowest verification command for the highest-ranked
	// non-test file in the edit. Never nil: the deriver has a residual floor.
	Verify *sem.SearchVerifyCommand `json:"verify,omitempty"`

	Warnings           []sem.ProviderWarning `json:"warnings,omitempty"`
	PartialFailures    []sem.PartialFailure  `json:"partial_failures"`
	CommittedCacheHit  bool                  `json:"committed_cache_hit"`
	EditedCacheHit     bool                  `json:"edited_cache_hit"`
	IndexCacheDisabled bool                  `json:"index_cache_disabled,omitempty"`
	IndexLatencyMS     int64                 `json:"index_latency_ms"`
	QueryLatencyMS     int64                 `json:"query_latency_ms"`
	TotalLatencyMS     int64                 `json:"total_latency_ms"`
}

