func capPosteditSections(response posteditResponse, limit int) posteditResponse {
	if limit > 0 && len(response.Symbols) > limit {
		response.Symbols = response.Symbols[:limit]
	}
	trimmed := make([]changedSymbol, 0, len(response.Symbols))
	for _, entry := range response.Symbols {
		if limit > 0 && len(entry.Callers) > limit {
			entry.Callers = entry.Callers[:limit]
		}
		trimmed = append(trimmed, entry)
	}
	response.Symbols = trimmed
	if limit > 0 && len(response.Risks) > limit {
		response.Risks = response.Risks[:limit]
	}
	return response
}

