              ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u=cc.get("usage") or {}
    return sum(u.get(k,0) or 0 for k in ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens"))

VERBS = ("search","impact","neighbors","callers","changed","def","grep","symbols","edges")

def scan(sid):
    g=collections.Counter(); nong=0; pairs=[]
    for f in tx.get(sid or "", []):
        lines=list(open(f,errors="replace"))
        for idx,line in enumerate(lines):
            try: o=json.loads(line)
            except Exception: continue
            m=o.get("message") or {}; body=m.get("content")
            if not isinstance(body,list): continue
            for b in body:
                if not isinstance(b,dict) or b.get("type")!="tool_use": continue
                nm=b.get("name")
                cmd=((b.get("input") or {}).get("command") or "") if nm=="Bash" else ""
                if ("entire graph" in cmd) or ("eg-q" in cmd):
                    v="?"
                    for cand in VERBS:
                        if f" {cand}" in cmd: v=cand; break
                    g[v]+=1; pairs.append((b.get("id"),v,cmd[:120]))
                else: nong+=1
    return g,nong,pairs

def results(sid):
    """map tool_use_id -> result text, so we can judge degeneracy from the ACTUAL answer"""
    out={}
    for f in tx.get(sid or "", []):
        for line in open(f,errors="replace"):
            try: o=json.loads(line)
            except Exception: continue
            m=o.get("message") or {}; body=m.get("content")
            if not isinstance(body,list): continue
            for b in body:
                if isinstance(b,dict) and b.get("type")=="tool_result":
                    c=b.get("content")
                    s=c if isinstance(c,str) else json.dumps(c)
                    out[b.get("tool_use_id")]=s
    return out

