for i in ids:
    res=results(E[i]["sid"])
    for tid,v,cmd in E[i]["pairs"]:
        s=res.get(tid,"")
        stat[v][0]+=1; stat[v][2]+=len(s)
        low=s.lower()
        if (not s) or len(s)<120 or any(d in low for d in DEG): stat[v][1]+=1
print(f"  {'verb':<10} {'calls':>5} {'degen':>6} {'%':>6} {'mean bytes':>11}")
tot=deg=0
for v,(c,d,byt) in sorted(stat.items(), key=lambda kv:-kv[1][0]):
