    if not grp: return None
    g=sum(E[i]["gtot"] for i in grp); e=sum(B[i]["nong"]-E[i]["nong"] for i in grp)
    se,sb=sum(E[i]["tok"] for i in grp),sum(B[i]["tok"] for i in grp)
