print(f"  {'group':<34} {'n':>3} {'G':>4} {'E':>5} {'rate':>6} {'net':>6} {'pooled':>8}")
groups = [
  ("used search at all",        [i for i in ids if E[i]["g"]["search"]>0]),
  ("never used search",         [i for i in ids if E[i]["g"]["search"]==0 and E[i]["gtot"]>0]),
  ("search-majority",           [i for i in ids if E[i]["gtot"]>0 and E[i]["g"]["search"]>E[i]["gtot"]/2]),
  ("grep-majority",             [i for i in ids if E[i]["gtot"]>0 and E[i]["g"]["grep"]>E[i]["gtot"]/2]),
  ("used a RELATION verb",      [i for i in ids if (E[i]["g"]["callers"]+E[i]["g"]["impact"]+E[i]["g"]["neighbors"]+E[i]["g"]["changed"])>0]),
  ("lexical only (grep/def)",   [i for i in ids if E[i]["gtot"]>0 and E[i]["g"]["search"]==0 and (E[i]["g"]["callers"]+E[i]["g"]["impact"])==0]),
]
for lab,grp in groups:
    r=rate(grp)
    if r: print(f"  {lab:<34} {r[5]:>3} {r[0]:>4} {r[1]:>5} {r[2]:>6.2f} {r[3]:>+6d} {r[4]:>7.1f}%")

print("\n=== IF EVERY DEGENERATE CALL HAD BEEN A GOOD ONE ===")
good_rate_grp=[i for i in ids if E[i]["g"]["search"]>0]
gr=rate(good_rate_grp)
print(f"  observed rate on search-using sessions : {gr[2]:.2f}")
G=sum(E[i]['gtot'] for i in ids); Eall=sum(B[i]['nong']-E[i]['nong'] for i in ids)
for assumed in (1.0,1.5,2.0,2.82,3.59):
    newE = (tot-deg)*assumed + deg*assumed   # all calls at the assumed rate
    print(f"  all {tot} calls at rate {assumed:>4.2f} -> E={newE:>5.0f}  net={newE-G:>+5.0f}  "
          f"(need net +191)  => {'REACHES 15%' if newE-G>=191 else 'short'}")
print("\n  NOTE n: the 4-call and 5-call buckets are n=3 and n=2. This project's own drill forbids")
print("  reading sub-groups of 3-7 from a single cell. Treat every split above as a hypothesis.")

