#!/usr/bin/env python3
"""THE DISCRIMINATOR. The 23.3-call refinement span is 43% of the session. Two possible causes,
with opposite implications:

  (A) DISCOVERING NEW SITES  -- later edits touch files/sites the agent had not yet edited.
      => the graph CAN predict these deterministically (related sites / same-pattern siblings).
      => a completeness answer at the FIRST edit collapses the span. BIG LEVER.

  (B) RE-EDITING THE SAME SITE -- later edits revisit a file already edited, getting logic right.
      => that is reasoning quality; no code graph can supply it. NO LEVER.

Measure the split. READ-ONLY."""
import json, os, glob, statistics, collections

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)
EDIT={"Edit","MultiEdit","Write","NotebookEdit"}

def edits(sid):
    out=[]
    for f in tx.get(sid or "", []):
        for line in open(f,errors="replace"):
            try: o=json.loads(line)
            except Exception: continue
            m=o.get("message") or {}; body=m.get("content")
            if not isinstance(body,list): continue
            for b in body:
                if not isinstance(b,dict) or b.get("type")!="tool_use": continue
                if b.get("name") not in EDIT: continue
                inp=b.get("input") or {}
                out.append(inp.get("file_path") or inp.get("notebook_path") or "")
    return out

def arm(a):
    base=f"{S}/results/REP50_r1_{a}/{a}"; o={}
    for i in sorted(os.listdir(base)):
        if i.startswith('.'): continue
        cc=f"{base}/{i}/cc_out.json"; pf=f"{base}/{i}/patch.diff"
        if not os.path.exists(cc) or not os.path.getsize(cc): continue
        try: j=json.load(open(cc))
        except Exception: continue
        if not (j.get("total_cost_usd") or 0)>0: continue
        if not (os.path.exists(pf) and os.path.getsize(pf)): continue
        # files in the FINAL patch
        pfiles=set()
        for line in open(pf,errors="replace"):
            if line.startswith("+++ ") and "/dev/null" not in line:
                pfiles.add(line[4:].strip().lstrip("ab/").strip())
        o[i]=dict(e=edits(j.get("session_id")), pfiles=pfiles)
    return o

E,B=arm("eg"),arm("baseline")
ids=[i for i in sorted(set(E)&set(B))]

print("=== EDIT SEQUENCE: new file vs revisit ===")
for a,name in ((E,"eg"),(B,"baseline")):
    first=rev=0; nfiles=[]; nedits=[]
    revisit_per_file=collections.Counter()
    for i in ids:
        seen=set(); e=a[i]["e"]
        nedits.append(len(e))
        for p in e:
            if p in seen: rev+=1; revisit_per_file[p]+=1
            else: first+=1; seen.add(p)
        nfiles.append(len(seen))
    tot=first+rev
    print(f"  {name:<9} edits {tot:>4}  first-touch {first:>4} ({100*first/tot:.0f}%)  "
          f"REVISIT {rev:>4} ({100*rev/tot:.0f}%)   distinct files/session {statistics.mean(nfiles):.1f}  "
          f"edits/session {statistics.mean(nedits):.1f}")

print("\n=== WHERE IN THE SPAN DO NEW FILES APPEAR? ===")
print("  If the agent discovers new files LATE, a completeness answer at edit #1 would have helped.")
for a,name in ((E,"eg"),(B,"baseline")):
    late=0; tot=0; pos=[]
    for i in ids:
        seen=set(); e=a[i]["e"]
        for k,p in enumerate(e):
            if p not in seen:
                seen.add(p); tot+=1
                if k>0: late+=1; pos.append(k/max(1,len(e)-1))
    print(f"  {name:<9} first-touch edits that occur AFTER edit #1: {late}/{tot} = {100*late/tot:.0f}%"
          + (f"   mean position in span {statistics.mean(pos):.2f}" if pos else ""))

print("\n=== HOW MANY EDITED FILES NEVER MADE IT INTO THE FINAL PATCH? (wasted edits) ===")
for a,name in ((E,"eg"),(B,"baseline")):
    inp=out=0
    for i in ids:
        pf=a[i]["pfiles"]
        for p in set(a[i]["e"]):
            base=os.path.basename(p)
            if any(base==os.path.basename(q) for q in pf): inp+=1
            else: out+=1
    print(f"  {name:<9} edited files IN the final patch {inp}   NOT in it {out} "
          f"({100*out/(inp+out) if inp+out else 0:.0f}% wasted)")

print("\n=== THE VERDICT SPLIT ===")
e=E; first=rev=0
for i in ids:
    seen=set()
    for p in e[i]["e"]:
        if p in seen: rev+=1
        else: first+=1; seen.add(p)
print(f"  (A) discovering NEW sites  : {first} edits ({100*first/(first+rev):.0f}%)  -> graph-addressable")
print(f"  (B) re-editing SAME site   : {rev} edits ({100*rev/(first+rev):.0f}%)  -> NOT graph-addressable")
print(f"\n  6 calls/session is what 15% needs. eg has {statistics.mean(len(E[i]['e']) for i in ids):.1f} edits and")
print(f"  {statistics.mean(len(set(E[i]['e'])) for i in ids):.1f} distinct files per session.")

