for r in rows:
    print(f"{r['tag']:<24} {r['n']:>3} {r['pooled']:>+8.2f}% {r['dturn']:>+8.1f} {r['model']:<18} {r['eff'][:44]}")
print(f"\ncells with n>=20 and pooled>=+10%:")
