import json, os, glob

NEW=os.path.expanduser("~/pe1/graphmark/agentic-swebench")
OLD=os.path.expanduser("~/work/graphmark/agentic-swebench")

def toks(cc):
    mu=cc.get("modelUsage") or {}
    if mu:
        t=sum((m.get(k,0) or 0) for m in mu.values() for k in
              ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u=cc.get("usage") or {}
    return sum(u.get(k,0) or 0 for k in ("input_tokens","output_tokens",
               "cache_read_input_tokens","cache_creation_input_tokens"))

def read(p):
    f=f"{p}/cc_out.json"
    if not (os.path.exists(f) and os.path.getsize(f)>1): return None
    try: j=json.load(open(f))
    except Exception: return None
    return dict(tok=toks(j),turns=j.get("num_turns") or 0,usd=j.get("total_cost_usd") or 0,
                sub=j.get("subtype"))

def load(root,tag,arm):
    base=f"{root}/results/{tag}_r1_{arm}/{arm}"; o={}
    if not os.path.isdir(base): return o
    for i in os.listdir(base):
        if i.startswith('.'): continue
        r=read(f"{base}/{i}")
        pf=f"{base}/{i}/patch.diff"
        if r and r["usd"]>0 and os.path.exists(pf) and os.path.getsize(pf): o[i]=r
    return o

NE,NB=load(NEW,"R50FIX","eg"),load(NEW,"R50FIX","baseline")
OE,OB=load(OLD,"REP50","eg"),load(OLD,"REP50","baseline")
g=sorted(set(NE)&set(NB))
se=sum(NE[i]["tok"] for i in g); sb=sum(NB[i]["tok"] for i in g)
print(f"current n={len(g)}  eg {se:,}  base {sb:,}  = {100*(1-se/sb):+.2f}%\n")

TAIL=["sharkdp__bat-1892","redis__redis-11510"]
print("=== what the censored attempt DID capture (archived) ===")
half={}
for i in TAIL:
    for arm,d in (("eg",NEW+f"/results/R50FIX_r1_eg/eg"),("baseline",NEW+f"/results/R50FIX_r1_baseline/baseline")):
        for p in glob.glob(f"{d}/.{i}.capped1800.*"):
            r=read(p)
            if r:
                half[(i,arm)]=r
                print(f"  {i.split('__')[-1]:<14} {arm:<9} {r['tok']:>11,} tok  {r['turns']:>3}t  ${r['usd']:.2f}  {r['sub']}")
