print("\n=== SCENARIOS for the final n=50 ===")
def scenario(lab, pairs):
    e=se+sum(a for a,b in pairs); b=sb+sum(b for a,b in pairs)
    print(f"  {lab:<46} {100*(1-e/b):+7.2f}%   (delta {100*(1-e/b)-100*(1-se/sb):+.2f}pt)")

# 1. they repeat REP50 ratios, scaled by this cell's baseline inflation on the 48
infl_num=sum(NB[i]["tok"] for i in g if i in OB); infl_den=sum(OB[i]["tok"] for i in g if i in OB)
infl=infl_num/infl_den if infl_den else 1.0
print(f"  (baseline inflation on the measured 48: x{infl:.2f})")
p=[]
for i in TAIL:
    if i in OE and i in OB:
        b=OB[i]["tok"]*infl; p.append((b*(OE[i]["tok"]/OB[i]["tok"]), b))
scenario("both repeat their REP50 ratio", p)

# 2. use the captured half where we have it, REP50 ratio for the missing half
p=[]
for i in TAIL:
    if (i,"eg") in half and i in OE and i in OB:
        e=half[(i,"eg")]["tok"]; p.append((e, e/(OE[i]["tok"]/OB[i]["tok"])))
    elif (i,"baseline") in half and i in OE and i in OB:
        b=half[(i,"baseline")]["tok"]; p.append((b*(OE[i]["tok"]/OB[i]["tok"]), b))
scenario("captured half + REP50 ratio for the other", p)

# 3. both neutral
p=[]
for i in TAIL:
    if i in OB: b=OB[i]["tok"]*infl; p.append((b,b))
scenario("both land neutral (0%)", p)

# 4. both win 30%
p=[]
for i in TAIL:
    if i in OB: b=OB[i]["tok"]*infl; p.append((b*0.7,b))
scenario("both win +30%", p)
print("""
READ: bat-1892 lost -79.8% and redis-11510 won +68.4% in REP50 — they pull in OPPOSITE directions,
which is why the net effect is small in every scenario. The larger risk is bat-1892's absolute size:
its eg arm alone burned $8.40 / 101 turns in the censored attempt, so if it repeats that against a
cheap baseline it costs more than redis-11510's win recovers.""")

