"""Look INSIDE the live sessions: what are the agents actually doing right now?
Reads the streaming transcript for each running session. READ-ONLY."""
import json, os, glob, time, collections

S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
EDIT = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
LIVE = [("sharkdp__bat-1892", "baseline"), ("redis__redis-11510", "eg"),
        ("redis__redis-11510", "baseline")]

for iid, arm in LIVE:
    d = f"{S}/results/R50FIX_r1_{arm}/{arm}/{iid}"
    if not os.path.isdir(d):
        print(f"\n### {iid.split('__')[-1]} / {arm}: not started"); continue
    if os.path.exists(f"{d}/cc_out.json") and os.path.getsize(f"{d}/cc_out.json") > 1:
        print(f"\n### {iid.split('__')[-1]} / {arm}: FINISHED"); continue

    # find the newest transcript whose path mentions this instance+arm
    cands = [p for p in glob.glob(f"{PROJ}/*R50FIX*{arm}*{iid}*/*.jsonl")] or \
            [p for p in glob.glob(f"{PROJ}/*{iid}*/*.jsonl")]
    if not cands:
        print(f"\n### {iid.split('__')[-1]} / {arm}: no transcript yet"); continue
    f = max(cands, key=os.path.getmtime)
    age = (time.time() - os.path.getmtime(f))

    rows = []
    for line in open(f, errors="replace"):
        try: rows.append(json.loads(line))
        except Exception: pass

    calls = []          # (kind, detail)
    toks = 0
    for o in rows:
        m = o.get("message") or {}
        u = m.get("usage") or {}
        toks += sum(u.get(k, 0) or 0 for k in
                    ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens"))
        c = m.get("content")
        if not isinstance(c, list): continue
        for b in c:
            if not isinstance(b, dict) or b.get("type") != "tool_use": continue
            nm = b.get("name"); inp = b.get("input") or {}
            if nm == "Bash":   calls.append(("bash", (inp.get("command") or "")[:88]))
            elif nm in EDIT:   calls.append(("EDIT", os.path.basename(inp.get("file_path") or "")))
            elif nm == "Read": calls.append(("read", os.path.basename(inp.get("file_path") or "")))
            else:              calls.append((nm.lower()[:6], str(inp)[:60]))

    kinds = collections.Counter(k for k, _ in calls)
    graph = sum(1 for k, v in calls if k == "bash" and ("entire graph" in v or "eg-q" in v))
    edits = [v for k, v in calls if k == "EDIT"]
    print(f"\n### {iid.split('__')[-1]} / {arm}   —  {len(calls)} tool calls, ~{toks:,} tok, "
          f"last activity {age:.0f}s ago")
    print(f"    buckets: {dict(kinds)}   graph calls: {graph}")
    print(f"    edits so far ({len(edits)}): {', '.join(dict.fromkeys(edits)) or 'none yet'}")
    print(f"    last 6 actions:")
    for k, v in calls[-6:]:
        print(f"      {k:<5} {v}")

