"""Live look inside the running tail sessions. Transcript dirs slugify the checkout path, so
underscores and slashes become dashes: redis__redis-11510 -> redis--redis-11510. READ-ONLY."""
import json, os, glob, time, collections, re

S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
EDIT = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
BUILD = ("make","cmake","cargo","mvn","gradle","npm","npx","yarn","pytest","phpunit","composer",
         "bundle","rake","rspec","ctest","javac","tsc","jest","runtest","go build","go test")
EXPL = ("grep","rg ","find ","cat ","head ","tail ","sed -n","awk","ls ")

def slug(iid, arm):
    return f"R50FIX-r1-{arm}-{arm}-" + re.sub(r'[_/]', '-', iid)

for iid, arm in [("sharkdp__bat-1892","baseline"), ("redis__redis-11510","eg"),
                 ("redis__redis-11510","baseline")]:
    d = f"{S}/results/R50FIX_r1_{arm}/{arm}/{iid}"
    name = f"{iid.split('__')[-1]} / {arm}"
    cc = f"{d}/cc_out.json"
    if os.path.exists(cc) and os.path.getsize(cc) > 1:
        j = json.load(open(cc))
        print(f"\n### {name}: FINISHED  {j.get('num_turns')}t  "
              f"{round((j.get('duration_ms') or 0)/60000,1)}min  ${round(j.get('total_cost_usd') or 0,2)}  "
              f"{j.get('subtype')}")
        continue
    if not os.path.isdir(d):
        print(f"\n### {name}: not started"); continue

    pat = slug(iid, arm)
    cands = [p for p in glob.glob(f"{PROJ}/*/*.jsonl") if pat in p]
    if not cands:
        loose = re.sub(r'[_/]', '-', iid)
        cands = [p for p in glob.glob(f"{PROJ}/*/*.jsonl") if loose in p and f"-{arm}-" in p]
    if not cands:
        print(f"\n### {name}: RUNNING, no transcript matched (pattern {pat})"); continue

