        for repo in sorted(byrepo):
            if depth < len(byrepo[repo]):
                got.append(byrepo[repo][depth])
                if len(got)==q: break
        depth+=1
    if len(got)<q: print(f"  WARN {lang}: only {len(got)}/{q} available")
    pick += got

print(f"multilingual picked: {len(pick)}")
c=collections.Counter(r["language"] for r in pick)
for k in QUOTA: print(f"  {k:<12} {c.get(k,0)}/{QUOTA[k]}")
print(f"  exposure: {dict(collections.Counter(expo(r['instance_id']) for r in pick))}")

# --- Pro python side --------------------------------------------------------
d=load_dataset("ScaleAI/SWE-bench_Pro")["test"]
py=[r for r in d if r["repo_language"].lower()=="python"]
byrepo=collections.defaultdict(list)
for r in py: byrepo[r["repo"]].append(r)
for k in byrepo: byrepo[k].sort(key=lambda r:r["instance_id"])
ppick=[]; depth=0
while len(ppick)<5:
    for repo in sorted(byrepo):
        if depth < len(byrepo[repo]):
            ppick.append(byrepo[repo][depth])
            if len(ppick)==5: break
    depth+=1
print(f"\nPro python picked: {len(ppick)}")
for r in ppick: print(f"  {r['instance_id'][:62]:<62} {r['repo']}")
print(f"  already run by us: {sum(1 for r in ppick if r['instance_id'] in run)}")
print(f"  graphs present   : {sum(1 for r in ppick if has_graph(r['instance_id']))}/5")

out={"instances":pick,"pro_python":[dict(r) for r in ppick]}
json.dump(out, open(f"{S}/tasks/rep50x_draft.json","w"), indent=1)
print(f"\nwritten rep50x_draft.json  (45 multilingual + 5 pro, pro NOT yet schema-adapted)")
PY
