#!/usr/bin/env python3
"""After the graph answers, what does the agent search for?
(a) symbols the graph never mentioned   -> capability gap
(b) symbols the graph DID return        -> redundant verification (behaviour, addressable)
(c) files the graph already named       -> payload sufficient but ignored
Uses gq_calls.log.payload (what the graph returned) + the transcript (what happened next)."""
import json, glob, os, re, sys, collections, statistics
S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
CELL = sys.argv[1] if len(sys.argv) > 1 else "REP50X"

PATH_RX = re.compile(r'[\w./-]+\.(?:java|py|go|rs|rb|php|js|ts|tsx|jsx|c|cc|cpp|h|hpp|cs|kt|scala|swift|m|mm)\b')
IDENT_RX = re.compile(r'\b[A-Za-z_][A-Za-z0-9_]{3,}\b')
STOP = set('''the and for with that this from into your which when have will been were are was not but
class func function def return type struct impl public private static final void const let var
import package module export default new if else while true false null none self args kwargs
string int bool float list dict map set error err test tests file path name value data result
graph search line lines code file_path symbol symbols match matches found NONE'''.split())

def idents(s):
    return {w for w in IDENT_RX.findall(s or "") if w.lower() not in STOP}

def tool_calls(jsonl):
    out = []
    try:
        for line in open(jsonl, errors="ignore"):
            line = line.strip()
            if not line:
                continue
            try:
                j = json.loads(line)
            except Exception:
                continue
            if j.get("type") != "assistant":
                continue
            for c in ((j.get("message") or {}).get("content") or []):
                if isinstance(c, dict) and c.get("type") == "tool_use":
                    out.append((c.get("name", "?"), c.get("input") or {}))
    except Exception:
        pass
    return out

# map instance -> transcript, by matching the checkout path embedded in the project dir name
def transcripts(arm):
    m = {}
    for f in glob.glob(f"{S}/results/{CELL}_r1_{arm}/ccfg/projects/*/*.jsonl"):
        d = os.path.basename(os.path.dirname(f))
        m.setdefault(d, []).append(f)
    return m

GRAPHC = re.compile(r'(entire[- ]graph|eg-q|graph search|graph impact|graph neighbors)')
SEARCH_TOOLS = ("Grep", "Glob")
SEARCH_CMD = re.compile(r'\b(grep|rg|ag|ack|find|fd)\b')

agg = collections.Counter()
per_session = []
n_used = 0

for inst_dir in sorted(glob.glob(f"{S}/results/{CELL}_r1_eg/eg/*/")):
    iid = os.path.basename(inst_dir.rstrip("/"))
    pay = inst_dir + "gq_calls.log.payload"
    if not (os.path.exists(pay) and os.path.getsize(pay) > 0):
        continue
    blob = open(pay, errors="ignore").read()
    graph_files = {os.path.basename(p) for p in PATH_RX.findall(blob)}
    graph_syms = idents(blob)
    if not graph_syms and not graph_files:
        continue

    # find this instance's transcript: the project dir name contains the instance id
    tf = None
    for d in glob.glob(f"{S}/results/{CELL}_r1_eg/ccfg/projects/*/"):
        if iid.replace("__", "-").replace("_", "-").lower() in os.path.basename(d.rstrip("/")).lower():
            js = glob.glob(d + "*.jsonl")
            if js:
                tf = max(js, key=os.path.getsize)
                break
    if not tf:
        continue
    calls = tool_calls(tf)
    if not calls:
        continue
    n_used += 1

    first_graph = None
    for k, (nm, inp) in enumerate(calls):
        s = nm + " " + json.dumps(inp)[:600]
        if GRAPHC.search(s):
            first_graph = k
            break
    if first_graph is None:
        continue

    b = c = a = 0
    for nm, inp in calls[first_graph + 1:]:
        if nm in SEARCH_TOOLS:
            q = str(inp.get("pattern", "")) + " " + str(inp.get("glob", ""))
        elif nm == "Bash" and SEARCH_CMD.search(str(inp.get("command", ""))):
            q = str(inp.get("command", ""))
        elif nm == "Read":
            p = os.path.basename(str(inp.get("file_path", "")))
            if p and p in graph_files:
                c += 1
            continue
        else:
            continue
        qi = idents(q)
        if qi & graph_syms:
            b += 1
        else:
            a += 1
    agg["b_redundant_search"] += b
    agg["a_new_symbol_search"] += a
    agg["c_read_graph_file"] += c
    per_session.append((b, a, c))

print(f"{CELL}: post-graph behaviour, eg arm  (n={len(per_session)} sessions with a graph call and a transcript)")
if not per_session:
    print("  could not join payloads to transcripts"); raise SystemExit
tb = agg["b_redundant_search"]; ta = agg["a_new_symbol_search"]; tc = agg["c_read_graph_file"]
tot = tb + ta
N = len(per_session)
print()
print(f"  searches issued AFTER the graph answered: {tot}  ({tot/N:.1f}/session)")
print(f"    (b) for a symbol the graph ALREADY returned : {tb:>5}  {100*tb/tot if tot else 0:>5.1f}%   {tb/N:.1f}/sess")
print(f"    (a) for a symbol the graph never mentioned  : {ta:>5}  {100*ta/tot if tot else 0:>5.1f}%   {ta/N:.1f}/sess")
print(f"    (c) Read of a file the graph already named  : {tc:>5}          {tc/N:.1f}/sess")
print()
print(f"  ADDRESSABLE pool (b + c) = {tb+tc} calls = {(tb+tc)/N:.1f}/session")
print(f"  CAPABILITY gap    (a)    = {ta} calls = {ta/N:.1f}/session")
print()
print(f"  interpretation: if (b)+(c) dominate, the payload was sufficient and the agent")
print(f"  re-verified anyway -> a behaviour problem, addressable without new graph verbs.")
print(f"  25% needs -8.3 calls/session; addressable pool is {(tb+tc)/N:.1f}/session.")

