#!/usr/bin/env python3
"""Running savings for a live cell.
STRICT   = pairs where BOTH arms finished in this cell (the real number).
EXTENDED = plus eg sessions whose baseline is not done yet, compared against that instance's most
           recent baseline from an earlier cell. Indicative only: cross-cell baselines carry
           run-level noise (same instance re-run moves a median 36-43pt), so the extended figure is
           a progress read, not a result.
Usage: sav.py CELL [fallback_cells...]"""
import json, glob, os, sys, statistics
S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
CELL = sys.argv[1] if len(sys.argv) > 1 else "SMOKE12"
FALL = sys.argv[2:] or ["CS50B", "CS50", "REP50X"]   # most recent first

def T(cc):
    mu = cc.get("modelUsage") or {}
    if mu:
        t = sum((m.get(k, 0) or 0) for m in mu.values() for k in
                ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u = cc.get("usage") or {}
    return sum(u.get(k, 0) or 0 for k in ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens"))

def load(cell, arm):
    o = {}
    for f in glob.glob(f"{S}/results/{cell}_r1_{arm}/{arm}/*/cc_out.json"):
        if os.path.getsize(f) < 2: continue
        try: j = json.load(open(f))
        except Exception: continue
        p = os.path.dirname(f) + "/patch.diff"
        ok = (j.get("subtype") == "success" and (j.get("total_cost_usd") or 0) > 0
              and os.path.exists(p) and os.path.getsize(p) > 0)
        o[f.split("/")[-2]] = dict(t=T(j), ok=ok, n=j.get("num_turns") or 0, usd=j.get("total_cost_usd") or 0)
    return o

E, B = load(CELL, "eg"), load(CELL, "baseline")
strict = [i for i in sorted(set(E) & set(B)) if E[i]["ok"] and B[i]["ok"]]

def pooled(pairs):
    se = sum(x[0] for x in pairs); sb = sum(x[1] for x in pairs)
    return 100*(1-se/sb) if sb else float("nan")

