#!/usr/bin/env python3
"""RE-TEST the scope-creep finding with the transcript-matching bug FIXED.
Original step0.py used endswith(slug), which silently missed baseline-arm dirs that get TRUNCATED
with a random 6-char suffix on long ids. Measured drop: 0 eg / 3 baseline per cell, all the same
3 Python/swebench_pro instances. That makes the p=0.0009 claim asymmetric AND language-confounded.
Fix: substring match on slug[:46]. Also COUNTS unmatched instead of coercing missing->0."""
import json, glob, os, statistics, random, collections
random.seed(67)
S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")

def T(cc):
    mu = cc.get("modelUsage") or {}
    if mu:
        t = sum((m.get(k,0) or 0) for m in mu.values() for k in
                ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u = cc.get("usage") or {}
    return sum(u.get(k,0) or 0 for k in ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens"))

def load(cell, arm):
    o = {}
    for f in glob.glob(f"{S}/results/{cell}_r1_{arm}/{arm}/*/cc_out.json"):
        if os.path.getsize(f) < 2: continue
        try: j = json.load(open(f))
        except Exception: continue
        p = os.path.dirname(f) + "/patch.diff"
        o[f.split("/")[-2]] = dict(t=T(j),
            ok=(j.get("subtype")=="success" and (j.get("total_cost_usd") or 0)>0
                and os.path.exists(p) and os.path.getsize(p)>0))
    return o

def edited(cell, arm, iid, mode):
    slug = iid.replace("_","-").lower()
    for d in glob.glob(f"{S}/results/{cell}_r1_{arm}/ccfg/projects/*/"):
        base = os.path.basename(d.rstrip("/")).lower()
        hit = base.endswith(slug) if mode == "old" else (slug[:46] in base)
        if not hit: continue
        files = set()
        for f in glob.glob(d + "*.jsonl"):
            for line in open(f, errors="ignore"):
                line = line.strip()
                if not line: continue
                try: j = json.loads(line)
                except Exception: continue
                if j.get("type") != "assistant": continue
                for c in ((j.get("message") or {}).get("content") or []):
                    if isinstance(c, dict) and c.get("type")=="tool_use" and c.get("name") in ("Edit","MultiEdit","Write"):
                        p = (c.get("input") or {}).get("file_path","") or ""
                        if p and "/tmp" not in p: files.add(os.path.basename(p))
        return files
    return None

rows = []
for cell in ("REP50X","CS50","CS50B"):
    E,B = load(cell,"eg"), load(cell,"baseline")
    for i in sorted(set(E)&set(B)):
        if E[i]["ok"] and B[i]["ok"]:
            rows.append((100*(1-E[i]["t"]/B[i]["t"]), i, cell))

for mode in ("old","fixed"):
    print("=" * 78)
    print(f"MATCHING = {mode.upper()}")
    buckets = {"severe <-60%": [r for r in rows if r[0] < -60],
               "mid":           [r for r in rows if -60 <= r[0] <= 20],
               "winners >+20%": [r for r in rows if r[0] > 20]}
    dd = {}
    unmatched = 0
    for lab, sel in buckets.items():
        ds = []
        for sav, iid, cell in sel:
            a = edited(cell,"eg",iid,mode); b = edited(cell,"baseline",iid,mode)
            if a is None or b is None:
                unmatched += 1; continue
            ds.append(len(a)-len(b))
        dd[lab] = ds
        if ds:
            print(f"  {lab:<15} n={len(ds):<4} eg-minus-base filedelta {statistics.mean(ds):+.2f}")
    print(f"  unmatched (silently dropped): {unmatched}")
    s, w = dd.get("severe <-60%",[]), dd.get("winners >+20%",[])
    if len(s) >= 4 and len(w) >= 4:
        obs = statistics.mean(s) - statistics.mean(w)
        pool = s + w; c = 0
        for _ in range(20000):
            random.shuffle(pool)
            if abs(statistics.mean(pool[:len(s)]) - statistics.mean(pool[len(s):])) >= abs(obs): c += 1
        p = c/20000
        print(f"  severe {statistics.mean(s):+.2f} vs winners {statistics.mean(w):+.2f}  gap {obs:+.2f}  permutation p={p:.4f}"
              f"  {'SURVIVES' if p < 0.05 else 'DOES NOT SURVIVE'}")
    print()

