12	// posteditRepo builds a committed git repository from a path -> content map and
13	// returns its root. Everything postedit reads is either git or the files
14	// themselves, so a temp directory with one commit is the whole world it needs.
15	func posteditRepo(t *testing.T, files map[string]string) string {
16		t.Helper()
17		repo := t.TempDir()
18		git(t, repo, "init")
19		git(t, repo, "config", "user.name", "Entire Graph Test")
20		git(t, repo, "config", "user.email", "graph@example.com")
21		for path, content := range files {
22			write(t, repo, path, content)
23		}
24		git(t, repo, "add", ".")
25		git(t, repo, "commit", "-m", "initial")
26		return repo
27	}
28	
29	func posteditText(t *testing.T, repo string, extra ...string) string {
30		t.Helper()
31		var out bytes.Buffer
32		args := append([]string{"postedit", "--repo", repo, "--no-cache"}, extra...)
33		if err := Run(t.Context(), Options{Version: "0.1.0", Env: EntireEnv{RepoRoot: repo}, Stdout: &out}, args); err != nil {
34			t.Fatalf("postedit: %v", err)
35		}
36		return out.String()
37	}
38	
39	func posteditJSON(t *testing.T, repo string, extra ...string) posteditResponse {
40		t.Helper()
41		raw := posteditText(t, repo, append([]string{"--format", "json"}, extra...)...)
42		var response posteditResponse
43		if err := json.Unmarshal([]byte(raw), &response); err != nil {
44			t.Fatalf("decode postedit json: %v\n%s", err, raw)
45		}
46		return response
47	}
