52	// must say that rather than fail as an unknown flag.
53	func TestPosteditRejectsTreeSelectorsAndValidatesItsOwnFlags(t *testing.T) {
54		t.Parallel()
55		for _, flag := range []string{"--head", "--worktree"} {
56			_, err := parsePosteditFlags([]string{flag})
57			if err == nil {
58				t.Fatalf("%s was accepted", flag)
59			}
60			if !strings.Contains(err.Error(), "committed tree") {
61				t.Fatalf("%s rejection does not explain itself: %v", flag, err)
62			}
63		}
