#!/usr/bin/env python3
"""Per-loser deep read: the actual commands, the actual errors, what the extra calls WERE."""
import json, os, glob, re, sys, collections
S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
GQ = ("entire graph","entire-graph","eg-q")
ERR = re.compile(r"(error|Error|ERROR|failed|FAILED|cannot|Cannot|not found|No such|exit code [1-9]|Exception|panic|Traceback)")

def dig(arm, short):
    for d in glob.glob("%s/results/REP30F_r1_%s/ccfg/projects/*/" % (S, arm)):
        if short.replace("_","-").lower() not in os.path.basename(d.rstrip("/")).lower(): continue
        cmds = collections.Counter(); files = collections.Counter()
        errs = collections.Counter(); gq = []
        pend = {}; res = {}
        for f in sorted(glob.glob(d + "*.jsonl")):
            for line in open(f, errors="ignore"):
                try: j = json.loads(line)
                except Exception: continue
                t, m = j.get("type"), (j.get("message") or {})
                for c in (m.get("content") or []):
                    if not isinstance(c, dict): continue
                    if t == "assistant" and c.get("type") == "tool_use":
                        nm, inp = c.get("name",""), (c.get("input") or {})
                        cmd = str(inp.get("command","")) if nm == "Bash" else ""
                        if any(h in cmd for h in GQ):
                            gq.append(cmd[:80]); pend[c.get("id")] = ("GRAPH", cmd)
                        elif nm in ("Edit","MultiEdit","Write"):
                            fp = os.path.basename(inp.get("file_path","") or "")
                            if fp: files[fp] += 1
                            pend[c.get("id")] = ("EDIT", fp)
                        elif nm == "Bash":
                            # normalise: first two tokens
                            tk = cmd.strip().split()
                            sig = " ".join(tk[:2])[:44] if tk else "?"
                            cmds[sig] += 1
                            pend[c.get("id")] = ("BASH", cmd)
                        else:
                            pend[c.get("id")] = (nm, str(inp)[:60])
                    elif t == "user" and c.get("type") == "tool_result":
                        v = c.get("content")
                        txt = v if isinstance(v,str) else " ".join(
                            y.get("text","") for y in v if isinstance(y,dict)) if isinstance(v,list) else ""
                        kind = pend.get(c.get("tool_use_id"), ("?",""))[0]
                        if kind == "BASH":
                            for mm in ERR.finditer(txt[:600]):
                                errs[txt[max(0,mm.start()-30):mm.start()+70].replace("\n"," ")[:96]] += 1
        return cmds, files, errs, gq
    return None, None, None, None

for short in sys.argv[1:]:
    print("=" * 78)
    print("  %s" % short)
    for arm in ("eg","baseline"):
        cmds, files, errs, gq = dig(arm, short)
        if cmds is None: print("    %s: no transcript" % arm); continue
        print("    --- %s ---" % arm)
        print("      top commands: %s" % ", ".join("%s x%d" % (k,v) for k,v in cmds.most_common(6)))
        print("      files edited: %s" % ", ".join("%s x%d" % (k,v) for k,v in files.most_common(6)))
        if arm == "eg" and gq: print("      graph: %s" % " | ".join(gq[:3]))
        if errs:
            print("      recurring errors:")
            for k,v in errs.most_common(3): print("        x%-3d %s" % (v, k))
