        if good: ok.append(iid)
    return ok
GOK=gated_ids()
KEYS={iid.replace("_","-").lower()[:46]:iid for iid in GOK}
def scan(arm):
    out={}
    for d in sorted(glob.glob("%s/results/REP30F_r1_%s/ccfg/projects/*/"%(S,arm))):
        bn=os.path.basename(d.rstrip("/")).lower()
        iid=next((v for k,v in KEYS.items() if k in bn), None)
        if not iid: continue
        ev=[]
        for f in sorted(glob.glob(d+"*.jsonl")):
            for ln in open(f,errors="ignore"):
                try: r=json.loads(ln)
                except Exception: continue
                m=r.get("message")
                if not isinstance(m,dict): continue
                c=m.get("content")
                if not isinstance(c,list): continue
                if r.get("type")=="assistant":
                    ev.append(("amsg",None,None))
                    for blk in c:
                        if isinstance(blk,dict) and blk.get("type")=="tool_use":
                            ev.append(("use",blk.get("name",""),blk.get("input") or {}))
                elif r.get("type")=="user":
                    for blk in c:
                        if isinstance(blk,dict) and blk.get("type")=="tool_result":
