                    for f in FILEPAT.findall(pl or ""): named.add(f.split("/")[-1])
                continue
            cmd=""
            if isinstance(pl,dict): cmd=str(pl.get("command",""))
            fp=str((pl or {}).get("file_path","")).split("/")[-1] if isinstance(pl,dict) else ""
            if nm=="Bash" and GRAPH.search(cmd):
