                last_g=msgs
            elif nm in ("Read","View","NotebookRead"):
                reads+=1
                if fp and fp in named and fp not in edited: sav+=1
            elif nm in ("Edit","Write","MultiEdit","NotebookEdit"):
                edits+=1
                if fp: edited.add(fp)
        out[iid]=dict(msgs=msgs,g=g,batch=batch,reads=reads,sav=sav,edits=edits,named=len(named))
    return out
EG,BA=scan("eg"),scan("baseline")
both=[i for i in GOK if i in EG and i in BA]
n=len(both)
def mean(d,k,ids): return sum(d[i][k] for i in ids)/len(ids)
