#!/usr/bin/env python3
"""ALL losers and winners: is the waste GRAPH-CAUSED and therefore graph-fixable?
For every pair, split eg's reads/edits into:
  gold        - file is in the gold patch (useful work)
  graph-sent  - file was named by a graph payload but is NOT in gold  <- GRAPH-CAUSED WASTE
  self        - file eg found on its own, not in gold
RELATED SITES precision is ~9-10%, so if graph-sent dominates the losers, fixing that block is the fix.
"""
import json,os,glob,re
from collections import Counter
S=os.path.expanduser("~/pe1/graphmark/agentic-swebench")
GRAPH=re.compile(r"entire[ -]graph|eg-q\b")
FILEPAT=re.compile(r"[\w./\-]+\.(?:py|go|java|js|jsx|ts|tsx|rs|c|cc|cpp|h|hpp|php|rb|cs|kt|swift|scala)\b")
RELHDR=re.compile(r"^RELATED SITES",re.M)
SHREAD=re.compile(r'^\s*(?:sed|cat|head|tail|awk|nl)\b')
def txt(b):
    t=b.get("content")
    if isinstance(t,str): return t
    if isinstance(t,list): return "\n".join(x.get("text","") for x in t if isinstance(x,dict))
    return ""
def goldset(p): return set(l[6:].strip().split("/")[-1] for l in (p or "").splitlines() if l.startswith("+++ b/"))
for CELL,TF in (("HOLD50","holdout50.json"),):
    j=json.load(open(S+"/tasks/"+TF)); ins=j.get("instances") if isinstance(j,dict) else j
    GOLD={r["instance_id"]:goldset(r.get("patch")) for r in ins}
    IDS=[r["instance_id"] for r in ins]
    def cost(arm,i):
        f="%s/results/%s_r1_%s/%s/%s/cc_out.json"%(S,CELL,arm,arm,i); p=os.path.dirname(f)+"/patch.diff"
        if not(os.path.exists(f) and os.path.getsize(f)>1): return None
        try: k=json.load(open(f))
        except Exception: return None
        if not(k.get("subtype")=="success" and (k.get("total_cost_usd") or 0)>0 and os.path.exists(p) and os.path.getsize(p)>0): return None
        return float(k.get("total_cost_usd") or 0)
    def analyse(arm,i):
        key=i.replace("_","-").lower()[:46]
        for d in glob.glob("%s/results/%s_r1_%s/ccfg/projects/*/"%(S,CELL,arm)):
            if key not in os.path.basename(d.rstrip("/")).lower(): continue
            named=set(); relnamed=set(); pend=False
            gold=GOLD.get(i,set()); g=sent=self_=goldw=0
            evs=[]
            for f in sorted(glob.glob(d+"*.jsonl")):
                for ln in open(f,errors="ignore"):
                    try: r=json.loads(ln)
                    except Exception: continue
                    m=r.get("message")
                    if not isinstance(m,dict): continue
                    c=m.get("content")
                    if not isinstance(c,list): continue
                    if r.get("type")=="assistant":
                        for b in c:
                            if isinstance(b,dict) and b.get("type")=="tool_use": evs.append(("use",b))
                    elif r.get("type")=="user":
                        for b in c:
                            if isinstance(b,dict) and b.get("type")=="tool_result": evs.append(("res",b))
            for kind,b in evs:
                if kind=="use":
                    nm=b.get("name",""); inp=b.get("input") or {}
                    cmd=str(inp.get("command","")); fp=str(inp.get("file_path","")).split("/")[-1]
                    if nm=="Bash" and GRAPH.search(cmd): g+=1; pend=True; continue
                    isread = nm in ("Read","View") or (nm=="Bash" and SHREAD.match(cmd))
                    isedit = nm in ("Edit","Write","MultiEdit")
                    if not (isread or isedit): continue
                    t=fp or (FILEPAT.findall(cmd)[-1].split("/")[-1] if FILEPAT.findall(cmd) else "")
                    if not t: continue
                    if t in gold: goldw+=1
                    elif t in named: sent+=1
                    else: self_+=1
                else:
                    if pend:
                        p=txt(b); pend=False
                        for x in FILEPAT.findall(p): named.add(x.split("/")[-1])
                        mm=RELHDR.search(p)
                        if mm:
                            for x in FILEPAT.findall(p[mm.start():]): relnamed.add(x.split("/")[-1])
            return dict(g=g,gold=goldw,sent=sent,self=self_,rel=len(relnamed))
        return None
    rows=[]
    for i in IDS:
        e,b=cost("eg",i),cost("baseline",i)
        if not(e and b): continue
        ae=analyse("eg",i)
        if not ae: continue
        rows.append((100*(1-e/b),i.split("__")[-1],ae))
    L=[r for r in rows if r[0]<=0]; W=[r for r in rows if r[0]>0]
    print("  %s  n=%d  losers=%d winners=%d"%(CELL,len(rows),len(L),len(W)))
