package gitutil

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func newWorktreeRepo(t *testing.T) string {
	t.Helper()
	repo := t.TempDir()
	git(t, repo, "init")
	git(t, repo, "config", "user.name", "Entire Graph Test")
