    if isinstance(x,list): return "".join(b.get("text","") if isinstance(b,dict) else str(b) for b in x)
    return ""
gold={}
for tf in glob.glob(f"{S}/tasks/*.json"):
    try: d=json.load(open(tf))
    except Exception: continue
    rows=d.get("instances",[]) if isinstance(d,dict) else (d if isinstance(d,list) else [])
    for i in rows:
        if isinstance(i,dict) and i.get("gold_files"):
            gold.setdefault(i["instance_id"], set(os.path.basename(x) for x in i["gold_files"]))
hit=[]; miss=[]; base=[]; totcalls=[]
for cd in sorted(glob.glob(f"{S}/results/*_r1_*")):
    m=re.match(r"(.+)_r1_(eg|baseline)$", os.path.basename(cd)); 
    if not m: continue
    arm=m.group(2)
    for f in glob.glob(cd+"/ccfg/projects/*/*.jsonl"):
        iid=None; pend={}; ev=[]; fp=None
        for ln in open(f,errors="ignore"):
            ln=ln.strip()
            if not ln or ln[0]!="{": continue
            try: r=json.loads(ln)
            except Exception: continue
            if iid is None and r.get("cwd"): iid=os.path.basename(r["cwd"])
            t=r.get("type"); c=(r.get("message") or {}).get("content")
            if t=="assistant" and isinstance(c,list):
                for b in c:
                    if not(isinstance(b,dict) and b.get("type")=="tool_use"): continue
                    nm=b.get("name",""); inp=b.get("input") or {}
                    isg = nm in("Bash","bash") and bool(GRAPH.search(inp.get("command") or ""))
                    ev.append(("g" if isg else ("f" if nm in("Read","read","Edit","MultiEdit","Write") else "o"),
                               os.path.basename(str(inp.get("file_path","")))))
                    if isg: pend[b.get("id")]=1
            elif t=="user" and isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get("type")=="tool_result" and b.get("tool_use_id") in pend:
                        if fp is None: fp=txt(b.get("content"))
                        del pend[b.get("tool_use_id")]
        if not iid or iid not in gold or not ev: continue
        gf=gold[iid]
        idx=next((k+1 for k,(kind,fn) in enumerate(ev) if kind=="f" and fn in gf), None)
        if idx is None: continue
        if arm=="baseline": base.append(idx); continue
        totcalls.append(len(ev))
        (hit if (fp and any(g in fp for g in gf)) else miss).append(idx)
print("=== CALLS-TO-GOLD, split by first-payload hit ===")
for lab,v in (("eg  HIT  (payload named gold)",hit),("eg  MISS (payload did not)",miss),("baseline (no tool)",base)):
    if v: print(f"  {lab:32} n={len(v):4}  mean {st.mean(v):5.2f}  median {st.median(v):5.1f}")
if hit and miss:
    p=len(hit)/(len(hit)+len(miss))
    cur=st.mean(hit)*p+st.mean(miss)*(1-p)
    print(f"\n  current hit rate {100*p:.1f}%   blended calls-to-gold {cur:.2f}   baseline {st.mean(base):.2f}")
    print(f"\n=== WHAT RAISING THE HIT RATE IS WORTH ===")
    print(f"  each displaced call ~= 1.23% cost (fitted cost~turns^1.179, ~96-msg session)")
    print(f"  {'hit rate':>10}{'calls-to-gold':>16}{'calls saved':>13}{'cost gain':>11}{'on top of +2.5%':>17}")
    for hr in (p, 0.70, 0.80, 0.90, 1.00):
        blended = st.mean(hit)*hr + st.mean(miss)*(1-hr)
        saved = cur - blended
        print(f"  {100*hr:>9.1f}%{blended:>16.2f}{saved:>13.2f}{saved*1.23:>10.2f}%{2.5+saved*1.23:>16.2f}%")
    print(f"\n  NOTE: this prices ONLY the locate phase. Median session is ~50 tool calls,")
    print(f"  so calls-to-gold is a small slice -- do not read these as total savings.")
OUTER
gcloud compute scp --zone us-east1-b --tunnel-through-iap "$SP/hitgain.py" graphbench-c:/tmp/hitgain.py 2>&1|tail -1
