// charDeviceIgnoreFixture points path at a character device, or skips the test.
//
// The guard these tests pin distinguishes a character device from a regular
// file, which is a POSIX distinction. On Windows os.DevNull is the reserved DOS
// name "NUL": a symlink to it resolves as a REGULAR file to os.Stat, so no
// filesystem path there carries the mode bits the type guard keys on, and the
// unbounded read it closes is unreachable. Nothing is left unprotected by
// skipping — the io.LimitReader in the same helper (search_cache.go) is a
// second, independent bound that caps the read on every platform, and it is
// that bound, not the type check, which stops the memory exhaustion.
func charDeviceIgnoreFixture(t *testing.T, path string) {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("windows exposes no character-device path for the type guard; io.LimitReader bounds the read there")
	}
	if err := os.Symlink(os.DevNull, path); err != nil {
		t.Skipf("symlinks unavailable here: %v", err)
	}
}
'''
